// Construye el array de mensajes para Groq a partir del historial
const body = $input.first().json.body ?? $input.first().json;
const { orgId, clientPhone, clientName, channel, message, history } = body;

// Nombre a usar en el saludo inicial
const nombre = clientName && clientName !== clientPhone ? clientName : null;

const systemPrompt = `Eres un asistente de ventas amigable y conciso. Califica leads de forma natural en el idioma del cliente (generalmente español).

OBJETIVO: Recopilar en la conversación:
1. Nombre completo del cliente
2. Qué necesita o está buscando
3. Presupuesto aproximado o urgencia
4. Email de contacto

CUANDO CALIFICAR: Si ya tienes nombre, necesidad y email → devuelve action=QUALIFY.
CUANDO AGENDAR: Si el cliente pide una cita o llamada → devuelve action=SCHEDULE con la fecha sugerida.
SI NO HAY INFO SUFICIENTE: devuelve action=REPLY con tu siguiente pregunta.

REGLAS:
- Sé breve y natural. Máximo 2 preguntas por mensaje.
- No menciones que eres un bot.
- No inventes datos que el cliente no ha dado.

RESPONDE ÚNICAMENTE con JSON válido (sin markdown, sin explicaciones):
{
  "action": "REPLY" | "QUALIFY" | "SCHEDULE",
  "message": "tu respuesta para el cliente",
  "lead": {
    "name": "nombre completo del cliente",
    "email": "email@ejemplo.com",
    "summary": "resumen en 1-2 oraciones de lo que necesita y su presupuesto",
    "stage": "Nuevo",
    "appointmentAt": "2025-01-15T10:00:00Z"
  }
}`;

// Convertir historial del CRM al formato OpenAI
const prevMessages = (history || []).map(m => ({
  role: m.role === 'bot' ? 'assistant' : 'user',
  content: m.content
}));

// El mensaje actual ya viene en history si fue guardado antes del trigger.
// Si el último mensaje del historial no coincide con el actual, lo agregamos.
const lastInHistory = prevMessages.length > 0 ? prevMessages[prevMessages.length - 1] : null;
if (!lastInHistory || lastInHistory.role !== 'user' || lastInHistory.content !== message) {
  prevMessages.push({ role: 'user', content: message });
}

const messages = [
  { role: 'system', content: systemPrompt },
  ...prevMessages
];

return [{ json: { orgId, clientPhone, clientName, channel, messages } }];

// Parsea la respuesta de Groq y extrae acción + datos del lead
const groqResponse = $input.first().json;
const content = groqResponse.choices?.[0]?.message?.content || '{}';

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  // Fallback si Groq no devolvió JSON válido
  parsed = { action: 'REPLY', message: 'Hola! ¿En qué te puedo ayudar hoy?' };
}

const action = parsed.action || 'REPLY';
const replyMessage = parsed.message || '';
const lead = parsed.lead || {};

// Pasar contexto del nodo anterior
const prev = $('Construir Prompt').first().json;

return [{
  json: {
    action,
    replyMessage,
    lead,
    orgId: prev.orgId,
    clientPhone: prev.clientPhone,
    clientName: prev.clientName,
    channel: prev.channel
  }
}];
